App.boot({id:'employees',title:'Employees & Roles',noCtx:true,render(el){const {esc,icon,formGrid,initials}=U,S=Store,db=S.db,me=App.user();
 const list=db.users.filter(u=>me.role==='owner'||u.role!=='owner');const actFarms=db.farms.filter(f=>!f.archived).map(f=>f.name);
 el.innerHTML=`<div class="page-head"><div><p>Office can add Farm Accountant, Farm Supervisor and Office users; only Owner can create an Owner account.</p></div><button class="btn" id="add">${icon('plus')} Add employee</button></div>
 <div class="grid g4">${Object.entries(S.ROLES).map(([k,v],i)=>`<div class="card kpi ${['','gold','blue',''][i]}"><div class="ic">${icon(['shield','farm','sprout','book'][i])}</div><div><div class="lbl">${v}</div><div class="val">${db.users.filter(u=>u.role===k&&u.active).length}</div><div class="sub">active</div></div></div>`).join('')}</div>
 <div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Team</h3><p>Every new employee gets demo PIN <b>1234</b>. Activation and farm changes are recorded in the audit log.</p></div></div><div id="t"></div><p class="hint">Payroll total (active): <b>${U.money(db.users.filter(u=>u.active&&(me.role==='owner'||u.role!=='owner')).reduce((s,u)=>s+(Number(u.salary)||0),0))}</b> / month • <a href="salaries.html">Manage salary payments →</a></p></div>
 <div class="card" style="margin-top:16px"><h3 style="margin-bottom:10px">Role permissions</h3><div class="table-wrap"><table><thead><tr><th>Role</th><th>Farms visible</th><th>Can do</th></tr></thead><tbody><tr><td><b>Owner</b></td><td>All farms</td><td>Everything incl. creating Owner accounts, receiving stock</td></tr><tr><td><b>Office</b></td><td>All farms</td><td>Farms, employees (no Owner), godown, transfers, approvals, rules</td></tr><tr><td><b>Farm Supervisor</b></td><td>Assigned farm</td><td>Stock receiving, usage and field overview</td></tr><tr><td><b>Farm Accountant</b></td><td>Assigned farm</td><td>Hari ledgers, income, expenses and stock usage</td></tr></tbody></table></div><p class="hint">Kamdar has no login. This is a visual preview, not server-enforced authorization.</p></div>`;
 U.dataTable(document.getElementById('t'),{rows:list,filters:[{label:'Role',options:Object.values(S.ROLES),get:u=>S.ROLES[u.role]},{label:'Status',options:['Active','Disabled'],get:u=>u.active?'Active':'Disabled'}],columns:[
  {label:'Name / Username',value:u=>u.name+' '+u.username,html:u=>`<div class="row" style="flex-wrap:nowrap"><span class="avatar" style="width:32px;height:32px;font-size:12px">${esc(initials(u.name))}</span><div><b>${esc(u.name)}</b><br><small>@${esc(u.username)}</small></div></div>`},
  {label:'Role',value:u=>S.ROLES[u.role],html:u=>`<span class="badge plain ${u.role==='owner'?'gold':u.role==='office'?'info':''}">${S.ROLES[u.role]}</span>`},
  {label:'Farm',value:u=>u.farm||'All farms'},{label:'Salary',num:1,value:u=>Number(u.salary)||0,html:u=>`<b>${U.money(u.salary)}</b><br><small>${esc(u.payType||'')}</small>`},{label:'Status',value:u=>u.active?'Active':'Disabled',html:u=>u.active?'<span class="badge ok">Active</span>':'<span class="badge bad">Disabled</span>'},
  {label:'Actions',sort:false,html:u=>`<button class="btn secondary sm" data-farm="${esc(u.id)}" ${['owner','office'].includes(u.role)?'disabled':''}>Change farm</button> <button class="btn secondary sm" data-sal="${esc(u.id)}">Salary</button> <button class="btn ${u.active?'danger':'secondary'} sm" data-tog="${esc(u.id)}" ${u.id===me.id?'disabled title="You cannot disable yourself"':''}>${u.active?'Disable':'Enable'}</button>`}]});
 document.getElementById('add').onclick=()=>{U.modal({title:'Add employee',submit:'Add employee',body:formGrid([{name:'name',label:'Full name',attrs:'maxlength="80"'},{name:'username',label:'Username (unique)',attrs:'pattern="[A-Za-z0-9._\\-]{3,30}" title="3–30 letters, digits, dot, underscore or dash"',hint:'3–30 letters, digits, dot, underscore or dash'},{name:'role',label:'Role',options:[['accountant','Farm Accountant'],['supervisor','Farm Supervisor'],['office','Office'],['owner','Owner',me.role!=='owner']]},{name:'farm',label:'Assigned farm',options:actFarms,cls:'farmField'},{name:'salary',label:'Monthly salary (PKR)',type:'number',value:0,attrs:'min="0" step="1"'},{name:'payType',label:'Pay type',options:S.PAY_TYPES}])+'<p class="hint">Demo PIN for new employees: 1234</p>',
  onSubmit:d=>{const role=d.role;if(me.role==='office'&&role==='owner')throw Error('Only Owner can create Owner accounts.');if(db.users.some(u=>u.username.toLowerCase()===d.username.trim().toLowerCase()))throw Error('Username already exists.');
   const u={id:'u'+Date.now(),name:d.name.trim(),username:d.username.trim(),role,farm:['owner','office'].includes(role)?'':d.farm,active:true,pin:'1234',salary:Number(d.salary)||0,payType:d.payType};db.users.push(u);S.log(`Created ${u.username}, role ${S.ROLES[role]}, farm ${u.farm||'All'}`);U.toast('Demo employee added. Sample PIN: 1234');App.refresh()}});
  const r=document.querySelector('.modal select[name=role]'),ff=document.querySelector('.modal .farmField');const tg=()=>ff.classList.toggle('hide',['office','owner'].includes(r.value));r.onchange=tg;tg()};
 U.on(el,'[data-sal]',b=>b.onclick=()=>App.editSalary(b.dataset.sal));
 U.on(el,'[data-tog]',b=>b.onclick=async()=>{const u=db.users.find(x=>x.id===b.dataset.tog);if(!u||u.id===me.id||(me.role==='office'&&u.role==='owner'))return;if(u.active&&!await U.confirmBox(`Disable ${u.name}? They will not be able to sign in.`,{ok:'Disable'}))return;u.active=!u.active;S.log(`${u.active?'Enabled':'Disabled'} ${u.username}`);U.toast('Employee status updated');App.refresh()});
 U.on(el,'[data-farm]',b=>b.onclick=()=>{const u=db.users.find(x=>x.id===b.dataset.farm);if(!u||!['supervisor','accountant'].includes(u.role))return;U.modal({title:'Assign farm — '+u.name,body:formGrid([{name:'farm',label:'Farm',options:actFarms,value:u.farm}]),onSubmit:d=>{if(!actFarms.includes(d.farm))throw Error('Choose an active farm.');const old=u.farm;u.farm=d.farm;S.log(`Changed ${u.username} farm ${old} → ${d.farm}`);U.toast('Farm assignment changed');App.refresh()}})})}});
